// Preferences are exercised through the dialog, then through the shell and a reload.
import { writeFileSync } from 'node:fs'
import { join } from 'node:path'

export async function settingsChecks({ proto, app, local, openPage, fail }) {
  const page = await openPage(local)
  const assert = (ok, why) => { if (!ok) fail(`settings: ${why}`) }
  const wait = ms => new Promise(r => setTimeout(r, ms))
  const until = async (expression, why) => {
    for (const end = Date.now() + 5000; Date.now() < end; await wait(50)) if (await page.run(expression)) return
    fail(`settings: ${why}`)
  }
  const click = selector => page.run(`document.querySelector(${JSON.stringify(selector)})?.click()`)
  const open = async () => {
    // Settings sits in the bar's ⋯ menu.
    await click('[data-bar] [data-act="open:more"]:not([aria-expanded="true"])')
    await click('[data-pop] [data-act=settings]')
    await until('!!document.querySelector("[data-settings-dialog]")', 'Settings did not open')
  }
  try {
    await open()
    assert(await page.run('localStorage.getItem("proto-theme") === null && document.querySelector("[data-setting-theme=system]").getAttribute("aria-pressed") === "true"'), 'a fresh browser does not default to system appearance')
    await until('document.querySelector("[data-settings-dialog]")?.contains(document.activeElement)', 'focus is outside the dialog')
    await click('[data-settings-category=feedback]')
    await wait(50)
    await click('[data-shoot=send-live] input')
    assert(await page.run('localStorage.getItem("proto-comments-live") === "1"'), 'automatic comment sending was not saved')
    await click('[data-settings-category=appearance]')
    await wait(50)
    await click('[data-setting-theme=dark]')
    await until('document.documentElement.classList.contains("dark")', 'dark appearance did not apply')
    await click('[data-setting-theme=system]')
    assert(await page.run('localStorage.getItem("proto-theme") === "system"'), 'system appearance was not saved')
    await click('[data-settings-category=browsing]')
    await wait(50)
    await click('[data-setting=sidebar] input')
    await click('[data-setting=review] input')
    await click('[data-setting-layout=stack]')
    assert(await page.run('document.querySelector("[data-setting-layout=stack]").getAttribute("aria-pressed") === "true"'), 'overview choice stayed stale after selecting List')
    assert(await page.run('localStorage.getItem("proto-side") === "0" && localStorage.getItem("proto-hints") === "0" && localStorage.getItem("proto-lobby") === "stack"'), 'browsing preferences were not saved')
    await click('[data-settings-category=session]')
    await wait(100)
    await until('!!document.querySelector("[data-setting=keep] input")', 'session pane did not open')
    const keepBefore = await page.run('document.querySelector("[data-setting=keep] input").checked')
    await click('[data-setting=keep] input')
    await until(`document.querySelector("[data-setting=keep] input").checked === ${!keepBefore} && !document.querySelector("[data-setting=keep] input").disabled`, 'keep forever did not save')
    const saved = await (await fetch(`${local}__proto/status`)).json()
    assert(saved.keep === !keepBefore, 'keep forever did not reach the server')
    await click('[data-setting=keep] input')
    await until(`document.querySelector("[data-setting=keep] input").checked === ${keepBefore} && !document.querySelector("[data-setting=keep] input").disabled`, 'keep forever did not restore')
    await page.run('window.__settingsFetch = window.fetch; window.fetch = (url, opts) => String(url).endsWith("/__proto/keep") ? Promise.resolve(new Response(JSON.stringify({ error: "Settings keep failure" }), { status: 500 })) : window.__settingsFetch(url, opts)')
    await click('[data-setting=keep] input')
    await until('document.querySelector("[data-settings-dialog] [role=alert]")?.textContent.includes("Settings keep failure") && !document.querySelector("[data-setting=keep] input").disabled', 'failed session update did not show an error or unlock the control')
    assert(await page.run(`document.querySelector("[data-setting=keep] input").checked === ${keepBefore}`), 'failed session update changed the saved preference')
    await page.run('window.fetch = window.__settingsFetch; delete window.__settingsFetch')
    // A stalled connection must release the pending controls and leave saved state intact.
    await page.run('window.__settingsFetch = window.fetch; window.fetch = (url, opts) => String(url).endsWith("/__proto/keep") ? new Promise((resolve,reject) => opts.signal.addEventListener("abort", () => reject(opts.signal.reason), { once: true })) : window.__settingsFetch(url, opts)')
    await click('[data-setting=keep] input')
    await until('document.querySelector("[data-setting=keep] input").disabled && document.querySelector("[data-setting-stop]").disabled', 'pending session update did not lock session controls')
    await wait(10_100)
    await until('document.querySelector("[data-settings-dialog] [role=alert]")?.textContent.includes("took too long") && !document.querySelector("[data-setting=keep] input").disabled && !document.querySelector("[data-setting-stop]").disabled', 'timed out session update did not unlock controls and report failure')
    assert(await page.run(`document.querySelector("[data-setting=keep] input").checked === ${keepBefore}`), 'timed out session update changed saved state')
    await page.run('window.fetch = window.__settingsFetch; delete window.__settingsFetch')
    await click('[data-setting=keep] input')
    await until(`document.querySelector("[data-setting=keep] input").checked === ${!keepBefore} && !document.querySelector("[data-setting=keep] input").disabled`, 'retry after timeout failed')
    await click('[data-setting=keep] input')
    await until(`document.querySelector("[data-setting=keep] input").checked === ${keepBefore} && !document.querySelector("[data-setting=keep] input").disabled`, 'retry did not restore saved state')
    await page.run('window.__settingsCopy = ""; Object.defineProperty(navigator, "clipboard", { configurable: true, value: { writeText: async text => { window.__settingsCopy = text } } })')
    await page.run('window.__copyCalls = 0; navigator.clipboard.writeText = text => { window.__copyCalls++; return new Promise(resolve => { window.__resolveCopy = () => { window.__settingsCopy = text; resolve() } }) }')
    await click('[data-setting-copy-url]')
    await until('document.querySelector("[data-setting-copy-url]").disabled && document.querySelector("[data-setting-reconnect]").disabled', 'pending copy did not disable both copy actions')
    await click('[data-setting-reconnect]')
    assert(await page.run('window.__copyCalls === 1'), 'overlapping copy actions started competing writes')
    await page.run('window.__resolveCopy()')
    await until('!document.querySelector("[data-setting-copy-url]").disabled && !document.querySelector("[data-setting-reconnect]").disabled', 'copy actions stayed disabled after completion')
    await page.run('navigator.clipboard.writeText = async text => { window.__settingsCopy = text }')
    await click('[data-setting-copy-url]')
    await until('window.__settingsCopy === document.querySelector("[data-setting-copy-url]").previousElementSibling.value', 'copy URL did not copy the public session address')
    await click('[data-setting-reconnect]')
    await until('window.__settingsCopy.includes("proto inbox --wait --session") && window.__settingsCopy.includes("smoke")', 'listener restart did not include the correct session')
    await page.run('navigator.clipboard.writeText = async () => { throw new Error("Denied") }')
    await click('[data-setting-reconnect]')
    await until('document.querySelector("[data-settings-dialog] textarea")?.value === window.__settingsCopy', 'denied clipboard did not expose the exact restart message for manual copying')
    await click('[data-setting-copy-url]')
    await until('document.querySelector("[data-settings-dialog] textarea")?.value === document.querySelector("[data-setting-copy-url]").previousElementSibling.value', 'denied clipboard did not expose the public URL for manual copying')
    await page.run('delete navigator.clipboard')
    await click('[data-settings-close]')
    await until('!document.querySelector("[data-settings-dialog]")', 'Settings did not close before status refresh check')
    await fetch(`${local}__proto/keep`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({keep: !keepBefore}) })
    await open()
    await until(`document.querySelector("[data-setting=keep] input")?.checked === ${!keepBefore}`, 'opening Settings did not refresh externally changed session status')
    await click('[data-setting=keep] input')
    await until(`document.querySelector("[data-setting=keep] input").checked === ${keepBefore} && !document.querySelector("[data-setting=keep] input").disabled`, 'external-status check did not restore saved state')
    const previousAgent = process.env.PROTO_AGENT
    try {
      for (const [host, label] of [['codex', 'Codex'], ['claude', 'Claude'], ['agent', 'Agent']]) {
        process.env.PROTO_AGENT = host
        proto(['url'])
        await until(`document.querySelector("[data-settings-dialog]").textContent.includes(${JSON.stringify(label + ' listener')})`, 'Settings listener did not follow the current host')
      }
    } finally {
      if (previousAgent === undefined) delete process.env.PROTO_AGENT; else process.env.PROTO_AGENT = previousAgent
      proto(['url'])
    }
    await click('[data-settings-category=shortcuts]')
    await until('document.querySelector("[data-settings-dialog]").textContent.includes("Send draft comments")', 'shortcuts tab is empty')
    const hash = await page.run('location.pathname')
    await page.key('Escape')
    await until('!document.querySelector("[data-settings-dialog]")', 'Escape did not close Settings')
    assert(await page.run('location.pathname') === hash, 'Escape navigated away from the current place')
    assert(await page.run('document.activeElement?.dataset.act === "open:more"'), 'closing did not restore focus to the menu that opened Settings')
    await page.run('location.reload()')
    await until('!!document.querySelector("[data-bar] [data-act=\\"open:more\\"]")', 'reload did not finish')
    await open()
    assert(await page.run('localStorage.getItem("proto-theme") === "system"'), 'startup replaced system appearance with a fixed theme')
    await click('[data-settings-category=feedback]')
    await wait(50)
    assert(await page.run('document.querySelector("[data-shoot=send-live] input").checked'), 'instant sending did not survive reload')
    await click('[data-settings-category=browsing]')
    await wait(50)
    assert(await page.run('!document.querySelector("[data-setting=sidebar] input").checked && !document.querySelector("[data-setting=review] input").checked && document.querySelector("[data-setting-layout=stack]").getAttribute("aria-pressed") === "true"'), 'preferences did not survive reload')
    await click('[data-settings-close]')
    await until('!document.querySelector("[data-settings-dialog]")', 'close button did not dismiss Settings')
    await open()
    await page.press(20, 20)
    await until('!document.querySelector("[data-settings-dialog]")', 'backdrop did not dismiss Settings')
    await page.run('localStorage.clear()')
  } finally { page.close() }

  proto(['add', 'settingsfx', '--title', 'Settings focus', '--variants', 'A:Page'])
  writeFileSync(join(app, 'src/protos/settingsfx/A.tsx'), 'export default function Page() { return <main><input aria-label="Keep these words" defaultValue="Initial" /></main> }')
  proto(['done', 'settingsfx'])
  const focus = await openPage(`${local}settingsfx/A`)
  try {
    await focus.run(`document.querySelector('[data-bar] [data-act="open:more"]').click(); document.querySelector('[data-act=focus]').click()`)
    await wait(300)
    await focus.run(`document.querySelector('[data-overlay] [data-act=settings]').click()`)
    await wait(200)
    await focus.key('Escape')
    await wait(200)
    assert(await focus.run(`document.activeElement?.closest('[data-overlay]') !== null && document.activeElement?.dataset.act === 'settings'`), 'focus did not return to the focus dock')
    assert(await focus.run(`getComputedStyle(document.querySelector('[data-zone]')).position === 'fixed'`), 'closing Settings left focus mode')
    await focus.run(`document.querySelector('[data-act=unfocus]').click(); document.querySelector('[data-bar] [data-act="open:device"]').click(); document.querySelector('[data-act="size:phone"]').click()`)
    for (const end = Date.now() + 5000; Date.now() < end; await wait(50)) {
      if (await focus.run(`!!document.querySelector('[data-view] iframe')?.contentWindow?.__protoTheme`)) break
    }
    await focus.appearance('light')
    await focus.run(`document.querySelector('[data-bar] [data-act="open:more"]:not([aria-expanded="true"])')?.click(); document.querySelector('[data-pop] [data-act=settings]').click()`)
    await wait(200)
    await focus.run(`document.querySelector('[data-settings-category=appearance]').click()` )
    await wait(50)
    await focus.run(`document.querySelector('[data-setting-theme=system]').click(); document.querySelector('[data-settings-close]').click()`)
    await wait(200)
    assert(await focus.run(`(() => { const w = document.querySelector('[data-view] iframe')?.contentWindow; const input = w?.document.querySelector('input'); if (!input) return false; input.value = 'Keep these words'; w.__settingsInput = input; return true })()`), 'device-view form did not mount')
    await focus.appearance('dark')
    await wait(300)
    assert(await focus.run(`(() => { const w = document.querySelector('[data-view] iframe')?.contentWindow; return document.documentElement.classList.contains('dark') && w?.document.documentElement.classList.contains('dark') && w.__settingsInput === w.document.querySelector('input') && w.__settingsInput.value === 'Keep these words' })()`), 'system appearance lost the device-view input state')
    await focus.run(`document.querySelector('[data-bar] [data-act="open:more"]:not([aria-expanded="true"])')?.click(); document.querySelector('[data-pop] [data-act=settings]').click()`)
    await wait(200)
    await focus.run(`document.querySelector('[data-settings-category=appearance]').click()` )
    await wait(50)
    await focus.run(`document.querySelector('[data-setting-theme=light]').click(); document.querySelector('[data-settings-close]').click()`)
    await wait(200)
    assert(await focus.run(`(() => { const w = document.querySelector('[data-view] iframe').contentWindow; return !w.document.documentElement.classList.contains('dark') && new URL(w.location.href).searchParams.get('theme') === 'light' && w.__settingsInput === w.document.querySelector('input') })()`), 'manual appearance lost state or left an old frame theme URL')
    await focus.run(`document.querySelector('[data-view] iframe').contentWindow.location.reload()`)
    await wait(1000)
    assert(await focus.run(`!document.querySelector('[data-view] iframe').contentDocument.documentElement.classList.contains('dark')`), 'frame reload restored an old theme')
  } finally { focus.close() }
  proto(['archive', 'settingsfx'])
  const phone = await openPage(local, { phone: true, width: 390, height: 844 })
  try {
    await phone.run('document.querySelector("[data-act=settings]").click()')
    await wait(400)
    assert(await phone.run('!!document.querySelector("[data-settings-handle]")'), 'phone settings is not a drawer')
    await phone.run('window.__settingsKeys = []; document.addEventListener("keydown", e => window.__settingsKeys.push(e.key), true)')
    await phone.key('w')
    assert(await phone.run('window.__settingsKeys.length === 0'), 'design page shortcuts heard a key inside phone settings')
    await phone.run('document.querySelector("[data-settings-category=session]").click()')
    await wait(400)
    assert(await phone.run('(() => { const r = document.querySelector("[data-settings-dialog]").getBoundingClientRect(); return r.width === innerWidth && Math.abs(r.bottom - innerHeight) < 2 })()'), 'phone drawer is not anchored to the screen bottom')
    const hash = await phone.run('location.pathname')
    const [x, y] = await phone.run('(() => { const r = document.querySelector("[data-settings-handle]").getBoundingClientRect(); return [r.x+r.width/2,r.y+r.height/2] })()')
    await phone.touch('touchStart', [[x, y]])
    for (let i = 1; i <= 8; i++) { await phone.touch('touchMove', [[x, y + Math.min(480, 844-y-15) * i/8]]); await wait(40) }
    await phone.touch('touchEnd', [])
    await wait(600)
    assert(await phone.run('!document.querySelector("[data-settings-dialog]")'), 'native touch swipe did not dismiss the drawer')
    assert(await phone.run('location.pathname') === hash, 'drawer swipe navigated away')
  } finally { phone.close() }
  console.log('Settings categories, session controls, keyboard focus, persistent preferences and native phone swipe passed')
}
